// The Tasks of every Project the caller reads (ADR 0017).
func (q *Queries) ListTasksForActiveMember(ctx context.Context, arg ListTasksForActiveMemberParams) ([]Task, error) {
	rows, err := q.db.Query(ctx, listTasksForActiveMember,
		arg.ActorUserID,
		arg.CompanyID,
		arg.HasStatuses,
		arg.Statuses,
		arg.HasPriorities,
		arg.Priorities,
		arg.HasAssignee,
		arg.AssigneeID,
		arg.HasExecutedBy,
		arg.ExecutedByAgentID,
		arg.HasDependenciesResolved,
		arg.DependenciesResolved,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Task{}
	for rows.Next() {
		var i Task
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.ConversationID,
			&i.Number,
			&i.Title,
			&i.Description,
			&i.Status,
			&i.Priority,
			&i.Labels,
			&i.StartDate,
			&i.DueDate,
			&i.AssigneeUserID,
			&i.ExecutedByAgentID,
			&i.CreatorUserID,
			&i.CreatorAgentID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CompletedAt,
			&i.Version,
			&i.MilestoneType,
			&i.ExecutionGeneration,
			&i.Key,
			&i.ProjectID,
			&i.WorkspaceGeneration,
			&i.ResultProposalOnly,
			&i.ResultReviewRequired,
			&i.AssignmentStatus,
			&i.ScheduledAt,
			&i.ScheduleFiredAt,
			&i.TaskScheduleID,
			&i.TaskScheduleGeneration,
			&i.ScheduleOccurrenceAt,
			&i.ScheduleDisposition,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

