const resolveTaskReference = `-- name: ResolveTaskReference :one
SELECT tasks.id
FROM tasks
JOIN companies
  ON companies.id = tasks.company_id
JOIN project_access
  ON project_access.company_id = tasks.company_id
 AND project_access.project_id = tasks.project_id
 AND project_access.user_id = $1::uuid
WHERE tasks.company_id = $2::uuid
  AND (
      lower(tasks.key) = lower($3::text)
      OR (
          tasks.number = $4::bigint
          AND lower(companies.task_prefix) = lower($5::text)
      )
  )
ORDER BY
    (tasks.key = $3::text) DESC,
    (lower(tasks.key) = lower($3::text)) DESC,
    tasks.number
LIMIT 1
`

type ResolveTaskReferenceParams struct {
	ActorUserID uuid.UUID `json:"actor_user_id"`
	CompanyID   uuid.UUID `json:"company_id"`
	Reference   string    `json:"reference"`
	LabelNumber int64     `json:"label_number"`
	LabelPrefix string    `json:"label_prefix"`
}

// The Task a person or Agent names instead of its id, for the two Task
// reads: its key in any letter case, else the {task_prefix}-{number} label
// the board shows, in the Company's own prefix and any letter case. A key
// that is exactly the reference wins, then a key equal in any case, then
// the label, so a key that reads like another Task's label still names its
// own Task. Keys are unique only in their exact letter case: when two keys
// equal the reference in some other case, the older Task (lower number)
// wins, so the same name always names the same Task. label_number is 0 when
// the reference is not label-shaped. Only Tasks in Projects the caller reads
// compete (ADR 0017): a hidden Task never shadows a visible one or reveals
// that its key exists. Only the id comes back; the read that follows still
// applies the caller's visibility and scope. The scan stays inside one
// Company's Tasks (company_id leads every tasks index).
func (q *Queries) ResolveTaskReference(ctx context.Context, arg ResolveTaskReferenceParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, resolveTaskReference,
		arg.ActorUserID,
		arg.CompanyID,
		arg.Reference,
		arg.LabelNumber,
		arg.LabelPrefix,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const taskHasNonterminalRunForCurrentExecutionGeneration = `-- name: TaskHasNonterminalRunForCurrentExecutionGeneration :one
SELECT EXISTS (
    SELECT 1
    FROM runs
    JOIN tasks
      ON tasks.id = runs.task_id
     AND tasks.company_id = runs.company_id
    WHERE runs.task_id = $1::uuid
      AND tasks.company_id = $2::uuid
      AND runs.task_execution_generation = tasks.execution_generation
      AND runs.status IN (
          'queued', 'dispatched', 'waiting_local_directory', 'running', 'deferred'
      )
)::boolean
`

type TaskHasNonterminalRunForCurrentExecutionGenerationParams struct {
	TaskID    uuid.UUID `json:"task_id"`
	CompanyID uuid.UUID `json:"company_id"`
}

// MarkFailed deliberately leaves its source Run active so the normal terminal
// callback still owns transcript, usage, and session state. A member cannot
// reopen that failed Task until the current generation has no active Run;
// otherwise the same Run could fail the reopened Task again with a new key.
func (q *Queries) TaskHasNonterminalRunForCurrentExecutionGeneration(ctx context.Context, arg TaskHasNonterminalRunForCurrentExecutionGenerationParams) (bool, error) {
	row := q.db.QueryRow(ctx, taskHasNonterminalRunForCurrentExecutionGeneration, arg.TaskID, arg.CompanyID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

const taskKeyTaken = `-- name: TaskKeyTaken :one
SELECT EXISTS (
    SELECT 1
    FROM tasks
    WHERE tasks.company_id = $1::uuid
      AND tasks.key = $2::text
)::boolean AS taken
`

type TaskKeyTakenParams struct {
	CompanyID uuid.UUID `json:"company_id"`
	Key       string    `json:"key"`
}

// Whether a Task already holds this key in the company. The mint path asks
// before inserting so a label-shaped key that reached the table earlier
// skips that number instead of failing every keyless create on the unique
// fence.
func (q *Queries) TaskKeyTaken(ctx context.Context, arg TaskKeyTakenParams) (bool, error) {
	row := q.db.QueryRow(ctx, taskKeyTaken, arg.CompanyID, arg.Key)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

const updateTask = `-- name: UpdateTask :one
WITH statement_clock AS MATERIALIZED (
    SELECT clock_timestamp()::timestamptz AS now_at
)
UPDATE tasks
SET milestone_type = $1::text,
    title = $2::text,
    description = $3::text,
    status = $4::text,
    priority = $5::text,
    labels = COALESCE($6::text[], tasks.labels),
    start_date = CASE WHEN $7::boolean THEN $8::date ELSE tasks.start_date END,
    due_date = CASE WHEN $7::boolean THEN $9::date ELSE tasks.due_date END,
    assignee_user_id = $10::uuid,
    executed_by_agent_id = $11::uuid,
    -- A confirmed handoff advances both generations in the same write
    -- (ADR 0014): the execution generation, so every Run of the previous
    -- generation — and every merge job and outcome report fenced on it —
    -- loses its hold on the Task; and the workspace generation, so the next
    -- assignee's daemon prepares a fresh root instead of continuing files
    -- another member left behind.
    execution_generation = CASE
        WHEN $12::boolean THEN tasks.execution_generation + 1
        ELSE tasks.execution_generation
    END,
    workspace_generation = CASE
        WHEN $12::boolean THEN tasks.workspace_generation + 1
        ELSE tasks.workspace_generation
    END,
    completed_at = CASE
        WHEN $4::text IN ('done', 'failed', 'cancelled')
            THEN COALESCE(tasks.completed_at, statement_clock.now_at)
        ELSE NULL
    END,
    updated_at = statement_clock.now_at,
    version = tasks.version + 1
FROM statement_clock
WHERE tasks.id = $13::uuid
  AND tasks.company_id = $14::uuid
  AND tasks.version = $15::bigint
  -- The assignee stays an active member, except that a Task already held by
  -- a departed member keeps them until someone reassigns it.
  AND EXISTS (
      SELECT 1 FROM company_members
      WHERE company_members.company_id = tasks.company_id
        AND company_members.user_id = $10::uuid
        AND (
            company_members.status = 'active'
            OR company_members.user_id = tasks.assignee_user_id
        )
  )
  AND (
      $11::uuid IS NULL
      OR EXISTS (
          SELECT 1 FROM agents
          WHERE agents.id = $11::uuid
            AND agents.company_id = tasks.company_id
            AND (
                agents.archived_at IS NULL
                OR agents.id = tasks.executed_by_agent_id
            )
      )
  )
  -- The write fence (ADR 0017), as in InsertTaskWithConversation: a person's
  -- write needs fence_permission on the Task's Project in this statement;
  -- NULL is a system writer acting on a Task it already holds.
  AND (
      $16::uuid IS NULL
      OR project_permission_held(
          tasks.company_id,
          tasks.project_id,
          $16::uuid,
          $17::text,
          $18::text[],
          $19::text[],
          $20::text[]
      )
  )
RETURNING tasks.id, tasks.company_id, tasks.conversation_id, tasks.number, tasks.title, tasks.description, tasks.status, tasks.priority, tasks.labels, tasks.start_date, tasks.due_date, tasks.assignee_user_id, tasks.executed_by_agent_id, tasks.creator_user_id, tasks.creator_agent_id, tasks.created_at, tasks.updated_at, tasks.completed_at, tasks.version, tasks.milestone_type, tasks.execution_generation, tasks.key, tasks.project_id, tasks.workspace_generation, tasks.result_proposal_only, tasks.result_review_required, tasks.assignment_status, tasks.scheduled_at, tasks.schedule_fired_at, tasks.task_schedule_id, tasks.task_schedule_generation, tasks.schedule_occurrence_at, tasks.schedule_disposition
`

